# brain/proactive.py — Ruby texting FIRST.
#
# Decides WHEN she reaches out on her own and WHY. No LLM calls: pure rules,
# so it is cheap to run every minute. The actual wording is generated by
# ResponseEngine.respond_proactive() using the "instruction" returned here.
#
# Design goals (so it feels human, not like a notification bot):
#   - She never texts a near-stranger: needs real history and some trust.
#   - Never in the small hours; at most a few a day, with long gaps.
#   - If you ignore her, she does NOT keep piling on: one unanswered text,
#     then (maybe) one stung follow-up a day later, then she goes quiet.
#   - Irritated Ruby doesn't text first.
#   - The wait before she reaches out is random, so it isn't clockwork.
#
# For testing, set the environment variable  RUBY_PROACTIVE_DEBUG=1  :
# it removes the relationship gate and quiet hours and shortens every timer.

import os
import json
import random
from datetime import datetime, timedelta
from typing import Optional, Dict

# ---------------- tunables ----------------
MIN_MESSAGES = 30            # total messages exchanged before she ever texts first
MIN_TRUST = 3.0              # ...and trust at least this (matches the "getting used to you" tier)
MIN_ATTACHMENT = 2.0         # ...or attachment at least this
QUIET_START, QUIET_END = 2, 8        # no texts from 02:00 to 07:59
MAX_PER_DAY = 3
MIN_GAP_HOURS = 3.0          # between two texts she starts herself
IDLE_MIN_MINUTES = 40        # random wait after your last message: 40..180 min
IDLE_MAX_MINUTES = 180
IGNORED_FOLLOWUP_HOURS = 24  # after an unanswered text, wait this long before one more
MISSING_AFTER_HOURS = 24     # silence this long -> she "noticed"

INSTRUCTIONS = {
    "random_thought": (
        "Something crosses your mind and you text them first — a stray thought, a small "
        "complaint, something from class, a half-formed question. One short line, two at "
        "most. Don't greet them like customer service."
    ),
    "late_night": (
        "It's late and you're awake. You text them first, a little less guarded than usual — "
        "but still you. One or two short lines."
    ),
    "missing": (
        "It's been a long time since they wrote and you noticed. You text first, but you "
        "would never admit you missed them — dry, a little accusing, maybe hurt underneath. "
        "One or two short lines."
    ),
    "ignored": (
        "You texted first earlier and they never answered. You're a bit stung and you hide "
        "it. One short, dry line. Don't beg."
    ),
}


def _debug() -> bool:
    return os.environ.get("RUBY_PROACTIVE_DEBUG", "") == "1"


class ProactiveEngine:
    def __init__(self, user_name: str = "not_set", storage_dir: Optional[str] = None,
                 rng: Optional[random.Random] = None):
        self.user_name = user_name
        self.rng = rng or random.Random()
        folder = storage_dir or os.getenv("FLET_APP_STORAGE_DATA", ".")
        self.path = os.path.join(folder, f"proactive_{user_name}.json")
        self._sent = []                       # list[datetime] of texts she started
        self._target_for = None               # last_user_ts the cached wait belongs to
        self._target_minutes = None
        self._load()

    # ---------------- persistence ----------------
    def _load(self):
        try:
            if os.path.exists(self.path):
                with open(self.path, "r", encoding="utf-8") as f:
                    raw = json.load(f).get("sent", [])
                self._sent = [datetime.fromisoformat(x) for x in raw]
        except Exception as e:
            print(f"⚠️ Proactive load failed: {e}")
            self._sent = []

    def _save(self):
        try:
            cutoff = datetime.now() - timedelta(days=7)
            self._sent = [t for t in self._sent if t >= cutoff]
            with open(self.path, "w", encoding="utf-8") as f:
                json.dump({"sent": [t.isoformat(timespec="seconds") for t in self._sent]}, f)
        except Exception as e:
            print(f"⚠️ Proactive save failed: {e}")

    def record_sent(self, when: Optional[datetime] = None):
        self._sent.append(when or datetime.now())
        self._save()

    def wipe(self):
        self._sent = []
        self._target_for = None
        self._target_minutes = None
        self._save()

    # ---------------- helpers ----------------
    def _wait_minutes(self, last_user_ts: datetime, attachment: float) -> float:
        """Random wait for this idle period; cached so it doesn't re-roll every minute."""
        if self._target_for != last_user_ts or self._target_minutes is None:
            if _debug():
                base = self.rng.uniform(1.0, 2.0)
            else:
                base = self.rng.uniform(IDLE_MIN_MINUTES, IDLE_MAX_MINUTES)
                base *= 1.0 - min(0.4, max(0.0, attachment) * 0.08)   # more attached -> sooner
            self._target_for = last_user_ts
            self._target_minutes = base
        return self._target_minutes

    # ---------------- the decision ----------------
    def decide(self, now: datetime, last_user_ts: Optional[datetime], rel: Dict,
               mood: str = "neutral", enabled: bool = True) -> Optional[Dict]:
        """Return {"reason", "instruction", "idle_hours"} if she should text now, else None."""
        if not enabled or last_user_ts is None:
            return None

        debug = _debug()

        # 1. Only with someone she actually knows
        if not debug:
            if rel.get("message_count", 0) < MIN_MESSAGES:
                return None
            if rel.get("trust", 0) < MIN_TRUST and rel.get("attachment", 0) < MIN_ATTACHMENT:
                return None

        # 2. Not when she's angry with them, not in the small hours
        if mood == "irritated":
            return None
        if not debug and QUIET_START <= now.hour < QUIET_END:
            return None

        # 3. Rate limits
        max_per_day = 50 if debug else MAX_PER_DAY
        min_gap = timedelta(minutes=2) if debug else timedelta(hours=MIN_GAP_HOURS)
        today = [t for t in self._sent if t.date() == now.date()]
        if len(today) >= max_per_day:
            return None
        last_sent = max(self._sent) if self._sent else None
        if last_sent and (now - last_sent) < min_gap:
            return None

        idle = now - last_user_ts
        if idle.total_seconds() < 0:
            return None
        idle_hours = idle.total_seconds() / 3600

        # 4. Unanswered texts: one, then maybe one stung follow-up a day later, then silence
        unanswered = [t for t in self._sent if t > last_user_ts]
        if len(unanswered) >= 2:
            return None
        if len(unanswered) == 1:
            wait = timedelta(minutes=3) if debug else timedelta(hours=IGNORED_FOLLOWUP_HOURS)
            if (now - unanswered[0]) < wait:
                return None
            reason = "ignored"
        else:
            # 5. Normal case: wait a random while after their last message
            attachment = rel.get("attachment", 0) or 0
            if idle.total_seconds() / 60 < self._wait_minutes(last_user_ts, attachment):
                return None
            if idle_hours >= MISSING_AFTER_HOURS:
                reason = "missing"
            elif now.hour >= 22 or now.hour < 2:
                reason = "late_night"
            else:
                reason = "random_thought"

        return {"reason": reason, "instruction": INSTRUCTIONS[reason], "idle_hours": round(idle_hours, 1)}
